157	export function createDeepSeekProvider(
158	  providerPath: string,
159	  options: DeepSeekProviderOptions = {},
160	): ApiProvider {
161	  const splits = providerPath.split(':');
162	  const modelName = splits.slice(1).join(':') || 'deepseek-chat';
163	  return new DeepSeekProvider(modelName, options);
164	}
