79	  /**
80	   * Loads a function from an external file
81	   * @param fileRef The file reference in the format 'file://path/to/file:functionName'
82	   * @returns The loaded function
83	   */
84	  private async loadExternalFunction(fileRef: string): Promise<Function> {
85	    let filePath = fileRef.slice('file://'.length);
86	    let functionName: string | undefined;
87	
88	    if (filePath.includes(':')) {
89	      const splits = filePath.split(':');
90	      if (splits[0] && isJavascriptFile(splits[0])) {
91	        [filePath, functionName] = splits;
92	      }
93	    }
94	
95	    try {
96	      const resolvedPath = path.resolve(cliState.basePath || '', filePath);
97	      logger.debug(
98	        `Loading function from ${resolvedPath}${functionName ? `:${functionName}` : ''}`,
99	      );
100	
101	      const requiredModule = await importModule(resolvedPath, functionName);
102	
103	      if (typeof requiredModule === 'function') {
104	        return requiredModule;
105	      } else if (
106	        requiredModule &&
107	        typeof requiredModule === 'object' &&
108	        functionName &&
109	        functionName in requiredModule
110	      ) {
111	        const fn = requiredModule[functionName];
112	        if (typeof fn === 'function') {
113	          return fn;
114	        }
115	      }
116	
117	      throw new Error(
118	        `Function callback malformed: ${filePath} must export ${
119	          functionName
120	            ? `a named function '${functionName}'`
121	            : 'a function or have a default export as a function'
122	        }`,
123	      );
124	    } catch (error: any) {
125	      throw new Error(`Error loading function from ${filePath}: ${error.message || String(error)}`);
126	    }
127	  }
