130	   * Executes a function callback with proper error handling
131	   */
132	  private async executeFunctionCallback(
133	    functionName: string,
134	    args: string,
135	    config: OpenAiCompletionOptions,
136	  ): Promise<string> {
137	    try {
138	      // Check if we've already loaded this function
139	      let callback = this.loadedFunctionCallbacks[functionName];
140	
141	      // If not loaded yet, try to load it now
142	      if (!callback) {
143	        const callbackRef = config.functionToolCallbacks?.[functionName];
144	
145	        if (callbackRef && typeof callbackRef === 'string') {
146	          const callbackStr: string = callbackRef;
147	          if (callbackStr.startsWith('file://')) {
148	            callback = await this.loadExternalFunction(callbackStr);
149	          } else {
150	            callback = new Function('return ' + callbackStr)();
151	          }
152	
153	          // Cache for future use
154	          this.loadedFunctionCallbacks[functionName] = callback;
155	        } else if (typeof callbackRef === 'function') {
156	          callback = callbackRef;
157	          this.loadedFunctionCallbacks[functionName] = callback;
158	        }
159	      }
160	
161	      if (!callback) {
162	        throw new Error(`No callback found for function '${functionName}'`);
163	      }
164	
165	      // Execute the callback
166	      logger.debug(`Executing function '${functionName}' with args: ${args}`);
167	      const result = await callback(args);
168	
169	      // Format the result
170	      if (result === undefined || result === null) {
