178	        }
179	      } else {
180	        return String(result);
181	      }
182	    } catch (error: any) {
183	      logger.error(`Error executing function '${functionName}': ${error.message || String(error)}`);
184	      throw error; // Re-throw so caller can handle fallback behavior
185	    }
186	  }
