48	// NOTE: loadApiProvider only accepts string paths. Callers use normalizeProviderRef
49	// (src/util/providerRef.ts) to classify provider shapes before calling this function.
50	export async function loadApiProvider(
51	  providerPath: string,
52	  context: LoadApiProviderContext = {},
53	): Promise<ApiProvider> {
54	  const { options = {}, basePath, env } = context;
55	
56	  // Merge environment overrides: context.env (test suite level) is base,
57	  // options.env (provider-specific) takes precedence for per-provider customization
58	  const mergedEnv: EnvOverrides | undefined =
59	    env || options.env ? { ...env, ...options.env } : undefined;
60	
61	  // Render ONLY environment variable templates at load time (e.g., {{ env.AZURE_ENDPOINT }})
62	  // This allows constructors to access real env values while preserving runtime templates
63	  // like {{ vars.* }} for per-test customization at callApi() time
64	  const renderedConfig = options.config
65	    ? renderEnvOnlyInObject(options.config, mergedEnv)
66	    : undefined;
67	  const renderedId = options.id ? renderEnvOnlyInObject(options.id, mergedEnv) : undefined;
68	
69	  const providerOptions: ProviderOptions = {
70	    id: renderedId,
71	    config: {
72	      ...renderedConfig,
73	      basePath,
74	    },
75	    env: mergedEnv,
76	  };
77	
78	  // Validate linkedTargetId if present (Promptfoo Cloud feature)
79	  if (providerOptions.config?.linkedTargetId) {
80	    await validateLinkedTargetId(providerOptions.config.linkedTargetId);
81	  }
82	
83	  // Render only env templates in provider path to avoid blanking unresolved placeholders.
84	  // This keeps behavior consistent with provider id/config rendering and file:// provider refs.
85	  const renderedProviderPath = renderEnvOnlyInObject(providerPath, mergedEnv);
86	
87	  if (isCloudProvider(renderedProviderPath)) {
88	    const cloudDatabaseId = getCloudDatabaseId(renderedProviderPath);
89	
90	    const cloudProvider = await getProviderFromCloud(cloudDatabaseId);
91	    if (isCloudProvider(cloudProvider.id)) {
92	      throw new Error(
93	        `This cloud provider ${cloudDatabaseId} points to another cloud provider: ${cloudProvider.id}. This is not allowed. A cloud provider should point to a specific provider, not another cloud provider.`,
94	      );
95	    }
96	
97	    // Merge local config overrides with cloud provider config
98	    // Local config takes precedence to allow per-eval customization
99	    const mergedOptions: ProviderOptions = {
100	      ...cloudProvider,
101	      config: {
102	        ...cloudProvider.config,
103	        ...options.config,
104	      },
105	      // Allow local overrides for these fields
106	      label: options.label ?? cloudProvider.label,
107	      transform: options.transform ?? cloudProvider.transform,
108	      delay: options.delay ?? cloudProvider.delay,
109	      prompts: options.prompts ?? cloudProvider.prompts,
110	      inputs: options.inputs ?? cloudProvider.inputs,
111	      // Merge all three env sources: context (base) -> cloud -> local (highest priority)
112	      env: {
113	        ...env, // Context env (from testSuite.env - proxies, tracing IDs, etc.)
114	        ...cloudProvider.env, // Cloud provider env overrides context
115	        ...options.env, // Local env overrides everything
116	      },
117	    };
118	
119	    logger.debug(
120	      `[Cloud Provider] Loaded ${cloudDatabaseId}, resolved to ${cloudProvider.id}${options.config ? ' with local config overrides' : ''}`,
121	    );
122	
123	    const mergedContext = {
124	      ...context,
125	      options: mergedOptions,
126	      env: mergedOptions.env,
127	    };
128	
129	    return loadApiProvider(cloudProvider.id, mergedContext);
130	  }
131	
132	  if (isProviderConfigFileReference(renderedProviderPath)) {
133	    const { configs, relativePath, wasArray } = readProviderConfigFile(
134	      renderedProviderPath,
135	      basePath,
136	    );
137	    const fileContent = configs[0];
138	    invariant(fileContent, `Provider config file ${relativePath} contains no providers`);
139	
140	    // Multi-provider files must go through loadApiProviders
141	    if (wasArray) {
142	      throw new Error(
143	        `Multiple providers found in ${relativePath}. Use loadApiProviders instead of loadApiProvider.`,
144	      );
145	    }
146	
147	    invariant(fileContent.id, `Provider config ${relativePath} must have an id`);
148	    logger.info('Loaded provider from config file', {
149	      providerConfigPath: relativePath,
150	      providerId: fileContent.id,
151	    });
152	
153	    // Merge file's env with context.env - context.env takes precedence
154	    // This allows callers to override file-defined defaults
155	    const mergedFileEnv: EnvOverrides | undefined =
156	      fileContent.env || mergedEnv ? { ...fileContent.env, ...mergedEnv } : undefined;
157	
158	    return loadApiProvider(fileContent.id, {
159	      basePath,
160	      options: {
161	        ...fileContent,
162	        env: mergedFileEnv,
163	      },
164	    });
165	  }
166	
167	  for (const factory of providerMap) {
168	    if (factory.test(renderedProviderPath)) {
169	      const ret = await factory.create(renderedProviderPath, providerOptions, context);
170	      ret.transform = options.transform;
171	      ret.delay = options.delay;
172	      ret.inputs = options.inputs;
173	      ret.label ||= renderEnvOnlyInObject(options.label || '', mergedEnv);
174	      return ret;
175	    }
176	  }
177	
178	  const errorMessage = dedent`
179	    Could not identify provider: ${chalk.bold(providerPath)}.
180	
181	    ${chalk.white(dedent`
182	      Please check your configuration and ensure the provider is correctly specified.
183	
184	      For more information on supported providers, visit: `)} ${chalk.cyan('https://promptfoo.dev/docs/providers/')}
185	  `;
186	  logger.error(errorMessage);
187	  throw new Error(errorMessage);
188	}
