  const modelName =
    splits[1] === 'chat' ? splits.slice(2).join(':') : splits.slice(1).join(':');

  if (!modelName) {
    throw new Error(
      'Abliteration provider requires a model name. Use format: abliteration:<model_name> or abliteration:chat:<model_name>',
    );
  }

  return new AbliterationProvider(modelName, providerOptions);
}
